// t(str, uiLanguage): translate a UI string. Falls back to the English original if no
// translation exists for the given uiLanguage — so it's always safe to call, and adding
// new UI text without a translation yet never breaks anything, it just stays in English.
function t(str, uiLanguage) {
  if (!uiLanguage || uiLanguage === "en") return str;
  return UI_STRINGS[str]?.[uiLanguage] || str;
}

