function buildQuestionMeta(raw, ctx) {
  return {
    ...raw,
    id: raw.id || `${ctx.chapterId}__${ctx.topicKey}__${ctx.difficulty}__${ctx.idx}`,
    chapterId: ctx.chapterId,
    chapterTitle: ctx.chapterTitle,
    topic: ctx.topicKey === "__chapter__" ? null : ctx.topicKey,
    difficulty: ctx.difficulty,
  };
}

function getMcqs(chapterId, chapterTitle, topicKey, difficulty) {
  const chapterData = MCQ_BANK[chapterId];
  if (!chapterData) return [];
  const topicData = chapterData[topicKey];
  if (!topicData) return [];
  const raw = topicData[difficulty] || [];
  return raw.map((r, idx) => buildQuestionMeta(r, { chapterId, chapterTitle, topicKey, difficulty, idx }));
}

// A question that's been filed under both "__chapter__" and its specific unit (intentionally,
// so it surfaces in both Whole-Chapter and Topic-wise practice) would otherwise appear twice
// in any pool that combines every topic at once (Whole Chapter mode, Mock Test). This keeps
// only the first copy encountered, matched on the question text itself since the two copies
// have different ids (their topicKey differs).
function dedupeQuestionPool(pool) {
  const seen = new Set();
  return pool.filter((q) => {
    const key = (q.en?.question || "").trim().toLowerCase();
    if (!key) return true; // never drop something we can't fingerprint
    if (seen.has(key)) return false;
    seen.add(key);
    return true;
  });
}

// "Whole Chapter" mode: combine questions from every unit of a chapter (at the chosen
// difficulty only) plus any chapter-level ("__chapter__") questions, then shuffle —
// so the mix and the order are both random each time the quiz is started.
function getMcqsForWholeChapter(chapter, chapterId, chapterTitle, difficulty) {
  const pool = [];
  const topicKeys = ["__chapter__", ...(chapter?.topics || []).map((t) => t.title)];
  topicKeys.forEach((tk) => {
    pool.push(...getMcqs(chapterId, chapterTitle, tk, difficulty));
  });
  return shuffleArray(dedupeQuestionPool(pool));
}

// Whole-Chapter "Sets" mode: mixed difficulty (all 4 levels together), fixed/stable order
// (sorted by id) rather than random — so "Set A" always means the same 20 questions every
// time you open this chapter, letting per-set progress make sense across sessions.
const SET_SIZE = 20;

function getChapterMcqsAllDifficulties(chapter, chapterId, chapterTitle) {
  const pool = [];
  const topicKeys = ["__chapter__", ...(chapter?.topics || []).map((t) => t.title)];
  topicKeys.forEach((tk) => {
    DIFFICULTIES.forEach((d) => pool.push(...getMcqs(chapterId, chapterTitle, tk, d.id)));
  });
  const deduped = dedupeQuestionPool(pool);
  // Stable order: sort by id so the same question always lands in the same set.
  deduped.sort((a, b) => (a.id < b.id ? -1 : a.id > b.id ? 1 : 0));
  return deduped;
}

// Splits a chapter's full question pool into fixed 20-question sets: [{ label: "Set A", questions: [...] }, ...]
function buildChapterSets(chapter, chapterId, chapterTitle) {
  const all = getChapterMcqsAllDifficulties(chapter, chapterId, chapterTitle);
  const sets = [];
  for (let i = 0; i < all.length; i += SET_SIZE) {
    const label = setLabelForIndex(sets.length);
    sets.push({ label, questions: all.slice(i, i + SET_SIZE) });
  }
  return sets;
}

// Set A, Set B, ... Set Z, then Set AA, Set AB, ... (spreadsheet-column style) in the
// unlikely event a chapter has more than 26 sets (520+ questions).
function setLabelForIndex(idx) {
  let n = idx;
  let label = "";
  do {
    label = String.fromCharCode(65 + (n % 26)) + label;
    n = Math.floor(n / 26) - 1;
  } while (n >= 0);
  return `Set ${label}`;
}

// Given a set's questions and the user's per-question progress, returns them reordered for
// resuming: unattempted questions first, then previously-incorrect ones, with previously-
// correct ones placed at the end (they're effectively done, but kept in the list so the set
// still shows all 20 and the "complete" check has something to point at).
function orderSetForResume(questions, questionProgress) {
  const unattempted = [];
  const incorrect = [];
  const correct = [];
  questions.forEach((q) => {
    const status = questionProgress[q.id];
    if (status === "correct") correct.push(q);
    else if (status === "incorrect") incorrect.push(q);
    else unattempted.push(q);
  });
  return [...unattempted, ...incorrect, ...correct];
}

// A set's completion status, for the Sets list screen: "complete" (all correct),
// "in_progress" (some attempted, not all correct yet), or "not_started".
function getSetStatus(questions, questionProgress) {
  let attemptedCount = 0;
  let correctCount = 0;
  questions.forEach((q) => {
    const status = questionProgress[q.id];
    if (status) attemptedCount += 1;
    if (status === "correct") correctCount += 1;
  });
  if (correctCount === questions.length && questions.length > 0) return "complete";
  if (attemptedCount > 0) return "in_progress";
  return "not_started";
}

function collectPaperMcqs(paper) {
  const pool = [];
  paper.sections.forEach((section) =>
    section.chapters.forEach((ch) => {
      ["__chapter__", ...(ch.topics || []).map((t) => t.title)].forEach((tk) => {
        DIFFICULTIES.forEach((d) => pool.push(...getMcqs(ch.id, ch.title, tk, d.id)));
      });
    })
  );
  return dedupeQuestionPool(pool);
}

// For the custom Mock Test builder: gather questions from only the chosen chapters
// (chapterIds) and only the chosen difficulties (difficultyIds), across all topics in
// those chapters plus their __chapter__ bucket.
function collectCustomMockMcqs(paper, chapterIds, difficultyIds) {
  const pool = [];
  paper.sections.forEach((section) =>
    section.chapters.forEach((ch) => {
      if (!chapterIds.includes(ch.id)) return;
      ["__chapter__", ...(ch.topics || []).map((t) => t.title)].forEach((tk) => {
        difficultyIds.forEach((diffId) => pool.push(...getMcqs(ch.id, ch.title, tk, diffId)));
      });
    })
  );
  return dedupeQuestionPool(pool);
}

