function getPyqsForPaper(paper, session) {
  const raw = PYQ_BANK[paper.id] || [];
  const filtered = session ? raw.filter((r) => r.session === session) : raw;
  return filtered.map((r, idx) => ({
    ...r,
    id: r.id || `pyq__${paper.id}__${session || "all"}__${idx}`,
    chapterId: paper.id,
    chapterTitle: paper.title,
    topic: r.session || null,
    difficulty: "pyq",
  }));
}

function getPyqSessions(paper) {
  const raw = PYQ_BANK[paper.id] || [];
  const sessions = [...new Set(raw.map((r) => r.session).filter(Boolean))];
  // sort chronologically: "June 2024" / "December 2024" etc.
  const monthRank = { January: 0, February: 1, March: 2, April: 3, May: 4, June: 5, July: 6, August: 7, September: 8, October: 9, November: 10, December: 11 };
  return sessions.sort((a, b) => {
    const [ma, ya] = a.split(" ");
    const [mb, yb] = b.split(" ");
    if (ya !== yb) return Number(ya) - Number(yb);
    return (monthRank[ma] ?? 0) - (monthRank[mb] ?? 0);
  });
}

// NOTES_BANK holds short revision notes, one combined summary per module. Structure:
// NOTES_BANK[chapterId] = { title, sections: [ { heading, points: [string, ...], formulas?: [string,...] } ] }
// Empty for now — notes get added here as they're provided.
const NOTES_BANK = {};

function shuffleArray(arr) {
  const a = [...arr];
  for (let i = a.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [a[i], a[j]] = [a[j], a[i]];
  }
  return a;
}

// ---------------------------------------------------------------------------
// SOUND EFFECTS — synthesized via Web Audio API, no external audio files needed.
// A single shared AudioContext is created lazily on first use (browsers require a user
// gesture before audio can play, and a tap/click on the answer option satisfies that).
// ---------------------------------------------------------------------------

let _sharedAudioCtx = null;
function getAudioCtx() {
  if (typeof window === "undefined") return null;
  if (!_sharedAudioCtx) {
    const Ctx = window.AudioContext || window.webkitAudioContext;
    if (!Ctx) return null;
    _sharedAudioCtx = new Ctx();
  }
  if (_sharedAudioCtx.state === "suspended") _sharedAudioCtx.resume();
  return _sharedAudioCtx;
}

// Plays a short tone. freq in Hz, durationMs, and an optional second freq for a two-note
// sequence (used for the "correct" chime and the "finish" fanfare).
function playTone(freq, durationMs, { type = "sine", volume = 0.15, delayMs = 0 } = {}) {
  const ctx = getAudioCtx();
  if (!ctx) return;
  const startAt = ctx.currentTime + delayMs / 1000;
  const osc = ctx.createOscillator();
  const gain = ctx.createGain();
  osc.type = type;
  osc.frequency.setValueAtTime(freq, startAt);
  gain.gain.setValueAtTime(0, startAt);
  gain.gain.linearRampToValueAtTime(volume, startAt + 0.01);
  gain.gain.exponentialRampToValueAtTime(0.0001, startAt + durationMs / 1000);
  osc.connect(gain);
  gain.connect(ctx.destination);
  osc.start(startAt);
  osc.stop(startAt + durationMs / 1000 + 0.02);
}

const SOUNDS = {
  correct: () => {
    playTone(880, 110, { type: "sine", volume: 0.14 });
    playTone(1318.5, 150, { type: "sine", volume: 0.12, delayMs: 90 });
  },
  incorrect: () => {
    playTone(220, 180, { type: "sine", volume: 0.13 });
  },
  tap: () => {
    playTone(600, 40, { type: "sine", volume: 0.06 });
  },
  finish: () => {
    [523.25, 659.25, 783.99, 1046.5].forEach((f, i) => playTone(f, 140, { type: "sine", volume: 0.12, delayMs: i * 90 }));
  },
};

// playSound(name, soundEnabled): the single entry point used throughout the app. Silently
// does nothing if sound is turned off in Settings, if the browser has no Web Audio support,
// or before any user gesture has unlocked audio — never throws either way.
function playSound(name, soundEnabled) {
  if (soundEnabled === false) return;
  try {
    SOUNDS[name]?.();
  } catch (e) {
    // Audio is a nice-to-have; never let it break the quiz flow.
  }
}

// ---------------------------------------------------------------------------
// FUZZY SEARCH (typo tolerance) — Levenshtein edit-distance based
// ---------------------------------------------------------------------------

function levenshtein(a, b) {
  const m = a.length, n = b.length;
  if (m === 0) return n;
  if (n === 0) return m;
  let prev = Array.from({ length: n + 1 }, (_, j) => j);
  for (let i = 1; i <= m; i++) {
    const cur = [i];
    for (let j = 1; j <= n; j++) {
      const cost = a[i - 1] === b[j - 1] ? 0 : 1;
      cur[j] = Math.min(cur[j - 1] + 1, prev[j] + 1, prev[j - 1] + cost);
    }
    prev = cur;
  }
  return prev[n];
}

// Returns true if `query` reasonably matches `text` — exact substring first,
// then a typo-tolerant word-by-word check (allows ~1 typo per 4 letters).
function fuzzyMatch(text, query) {
  const t = text.toLowerCase();
  const q = query.trim().toLowerCase();
  if (!q) return false;
  if (t.includes(q)) return true;

  const words = t.split(/[^a-z0-9]+/).filter(Boolean);
  const maxDist = q.length <= 4 ? 1 : q.length <= 8 ? 2 : 3;
  return words.some((w) => {
    if (w.length < 3) return false;
    // quick length gate to avoid expensive comparisons on very mismatched lengths
    if (Math.abs(w.length - q.length) > maxDist + 2) return false;
    return levenshtein(w, q) <= maxDist;
  });
}

