// ---------------------------------------------------------------------------
// USER-SCOPED PERSISTENCE
// Keys are namespaced by the signed-in user's email so that switching users
// on the same device (logout -> different login) never shows one person's
// bookmarks/mistakes/stats to another. Falls back to an anonymous bucket
// when no one is signed in (e.g. mid-auth-flow) so nothing throws.
// ---------------------------------------------------------------------------

function storageKeyFor(email, name) {
  const safeEmail = (email || "anon").toLowerCase().trim();
  return `cma_${name}_${safeEmail}`;
}

function loadPersisted(email, name, fallback) {
  try {
    const raw = localStorage.getItem(storageKeyFor(email, name));
    if (raw === null) return fallback;
    return JSON.parse(raw);
  } catch (e) {
    return fallback;
  }
}

function usePersistedState(email, name, fallback) {
  const [value, setValue] = useState(() => loadPersisted(email, name, fallback));
  const loadedForRef = React.useRef(email);

  // When the signed-in user changes (login/logout/switch account), reload
  // this piece of state from that user's own storage bucket instead of
  // carrying over whatever was in memory for the previous user.
  React.useEffect(() => {
    if (loadedForRef.current !== email) {
      loadedForRef.current = email;
      setValue(loadPersisted(email, name, fallback));
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [email]);

  React.useEffect(() => {
    try {
      localStorage.setItem(storageKeyFor(email, name), JSON.stringify(value));
    } catch (e) {
      // storage full or unavailable — fail silently, in-memory state still works this session
    }
  }, [email, name, value]);

  return [value, setValue];
}

// ---------------------------------------------------------------------------
// SHARED QUIZ STATE HOOK
// ---------------------------------------------------------------------------

function useQuizState(recordAnswer, language) {
  const [questions, setQuestions] = useState([]);
  const [currentQ, setCurrentQ] = useState(0);
  const [answers, setAnswers] = useState({});

  const start = (qs) => {
    setQuestions(qs);
    setCurrentQ(0);
    setAnswers({});
  };

  const handleAnswer = (qIdx, optionIdx) => {
    setAnswers((prev) => {
      if (prev[qIdx] !== undefined) return prev;
      recordAnswer(questions[qIdx], optionIdx, language);
      return { ...prev, [qIdx]: optionIdx };
    });
  };

  const score = useMemo(() => {
    let correct = 0;
    questions.forEach((q, i) => {
      const a = answers[i];
      if (a !== undefined) {
        const qd = q[language] || q.en;
        if (qd && a === qd.correctIndex) correct++;
      }
    });
    return { correct, total: questions.length, attempted: Object.keys(answers).length };
  }, [answers, questions, language]);

  return { questions, currentQ, setCurrentQ, answers, handleAnswer, start, score };
}

