function ChapterScreen({ paper, onSelectChapter, onOpenStudyNotes, uiLanguage }) {
  const { palette, styles } = useTheme();
  if (!paper) return null;
  return (
    <div style={styles.screenPad}>
      <div style={styles.sectionHeaderRow}>
        <div style={{ ...styles.paperTag, background: paper.color }}>{paper.code}</div>
      </div>
      <h2 style={styles.screenTitle}>{paper.title}</h2>

      {paper.pdfPath && (
        <button className="cma-tap-btn" style={styles.pdfDownloadCard} onClick={() => onOpenStudyNotes(paper)}>
          <div style={styles.pdfDownloadIconWrap}>
            <BookOpen size={17} color={paper.color} />
          </div>
          <div style={styles.pdfDownloadBody}>
            <div style={styles.pdfDownloadTitle}>{t("Read Official Study Notes", uiLanguage)}</div>
            <div style={styles.pdfDownloadSub}>ICMAI Syllabus 2022 — opens inside the app</div>
          </div>
          <ChevronRight size={17} color={palette.subtext2} />
        </button>
      )}

      {paper.sections.map((section) => (
        <div key={section.id} style={{ marginBottom: 22 }}>
          <div style={styles.subsectionLabel}>
            {section.title} <span style={styles.subsectionWeight}>· {section.weight}</span>
          </div>
          <div style={styles.cardList}>
            {section.chapters.map((ch) => (
              <button key={ch.id} style={styles.chapterCard} onClick={() => onSelectChapter(ch)}>
                <div style={styles.chapterCardMain}>
                  <div style={styles.chapterCardTitle}>{ch.title}</div>
                  <div style={styles.chapterCardMeta}>{ch.topics.length} {t("topics", uiLanguage)} · {ch.weight} {t("weightage", uiLanguage)}</div>
                </div>
                <ChevronRight size={19} color={palette.subtext2} />
              </button>
            ))}
          </div>
        </div>
      ))}
    </div>
  );
}

