// ---------------------------------------------------------------------------
// DIFFICULTY SELECTION
// ---------------------------------------------------------------------------

function DifficultyScreen({ chapter, topic, topicKey, mode, onSelect, uiLanguage }) {
  const { palette, styles } = useTheme();
  const countFor = (diffId) => {
    if (!chapter) return 0;
    if (mode === "topic" && topicKey) {
      return getMcqs(chapter.id, chapter.title, topicKey, diffId).length;
    }
    return getMcqsForWholeChapter(chapter, chapter.id, chapter.title, diffId).length;
  };
  return (
    <div style={styles.screenPad}>
      <h2 style={styles.screenTitle}>{topic || chapter?.title}</h2>
      <p style={styles.screenSub}>{t("Select difficulty level", uiLanguage)}</p>
      <div style={styles.cardList}>
        {DIFFICULTIES.map((d) => {
          const count = countFor(d.id);
          return (
            <button key={d.id} className="cma-tap-btn" style={styles.diffCardV2} onClick={() => onSelect(d.id)}>
              <div style={{ ...styles.diffIconCircle, background: `${d.color}14`, borderColor: d.color }}>
                <span style={{ fontSize: 14, fontWeight: 700, color: d.color, fontFamily: palette.displayFont }}>
                  {["I", "II", "III", "IV"][d.level - 1]}
                </span>
              </div>
              <div style={styles.diffCardBody}>
                <div style={styles.diffLevelBarsRow}>
                  {[1, 2, 3, 4].map((lvl) => (
                    <span
                      key={lvl}
                      style={{
                        ...styles.diffLevelBar,
                        background: lvl <= d.level ? d.color : palette.borderSoft,
                      }}
                    />
                  ))}
                </div>
                <span style={{ ...styles.diffLabel, color: d.color }}>{d.label}</span>
                <span style={styles.diffDesc}>{d.desc} · {count} {count === 1 ? t("question", uiLanguage) : t("questions", uiLanguage)}</span>
              </div>
              <ChevronRight size={18} color={palette.subtext2} />
            </button>
          );
        })}
      </div>
    </div>
  );
}

// ---------------------------------------------------------------------------
// WHOLE-CHAPTER SETS (fixed 20-question sets, mixed difficulty, with resume tracking)
// ---------------------------------------------------------------------------

function SetsScreen({ chapter, questionProgress, onSelectSet, uiLanguage }) {
  const { palette, styles } = useTheme();
  const sets = useMemo(
    () => (chapter ? buildChapterSets(chapter, chapter.id, chapter.title) : []),
    [chapter]
  );

  if (!chapter) return null;

  if (sets.length === 0) {
    return (
      <div style={styles.screenPad}>
        <h2 style={styles.screenTitle}>{chapter.title}</h2>
        <div style={styles.emptyState}>
          <div style={styles.emptyIconCircle}>
            <FileQuestion size={30} color={palette.subtext2} />
          </div>
          <h3 style={styles.emptyStateTitle}>{t("No questions here yet", uiLanguage)}</h3>
        </div>
      </div>
    );
  }

  return (
    <div style={styles.screenPad}>
      <h2 style={styles.screenTitle}>{chapter.title}</h2>
      <p style={styles.screenSub}>{t("Mixed-difficulty sets of 20 questions. Pick up right where you left off.", uiLanguage)}</p>
      <div style={styles.cardList}>
        {sets.map((set, i) => {
          const status = getSetStatus(set.questions, questionProgress);
          const correctCount = set.questions.filter((q) => questionProgress[q.id] === "correct").length;
          const statusColor = status === "complete" ? palette.success : status === "in_progress" ? palette.warn : palette.subtext2;
          const statusText =
            status === "complete"
              ? t("Complete", uiLanguage)
              : status === "in_progress"
              ? `${correctCount}/${set.questions.length} ${t("correct", uiLanguage)}`
              : t("Not started", uiLanguage);
          return (
            <button key={i} className="cma-tap-btn" style={styles.setCard} onClick={() => onSelectSet(i)}>
              <div style={{ ...styles.setIconCircle, background: `${statusColor}14`, borderColor: statusColor }}>
                {status === "complete" ? (
                  <CheckCircle2 size={18} color={statusColor} />
                ) : (
                  <span style={{ fontSize: 13, fontWeight: 700, color: statusColor, fontFamily: palette.displayFont }}>{set.label.replace("Set ", "")}</span>
                )}
              </div>
              <div style={styles.setCardBody}>
                <div style={styles.setCardTitle}>{set.label}</div>
                <div style={{ ...styles.setCardStatus, color: statusColor }}>{statusText}</div>
                <div style={styles.paperProgressTrack}>
                  <div style={{ ...styles.paperProgressFill, width: `${(correctCount / set.questions.length) * 100}%`, background: statusColor }} />
                </div>
              </div>
              <ChevronRight size={18} color={palette.subtext2} />
            </button>
          );
        })}
      </div>
    </div>
  );
}

// ---------------------------------------------------------------------------
// QUIZ SCREEN (shared by Practice + Mock Test)
// ---------------------------------------------------------------------------

function QuizScreen({ quiz, language, isBookmarked, onToggleBookmark, onFinish, emptyTitle, emptySub, showGoogleSearch, showCorrectAnswer = true, uiLanguage }) {
  const { palette, styles } = useTheme();
  const { questions, currentQ, setCurrentQ, answers, handleAnswer } = quiz;

  if (questions.length === 0) {
    return (
      <div style={styles.screenPad} className="cma-card-enter">
        <div style={styles.emptyState}>
          <div style={styles.emptyIconCircle}>
            <FileQuestion size={30} color={palette.subtext2} />
          </div>
          <h3 style={styles.emptyStateTitle}>{t("No questions here yet", uiLanguage)}</h3>
          <p style={styles.emptyStateText}>
            MCQs for <strong>{emptyTitle}</strong>{emptySub ? ` (${emptySub})` : ""} haven't been added yet. They'll show up here once added.
          </p>
        </div>
      </div>
    );
  }

  const q = questions[currentQ];
  const qData = q[language] || q.en;
  const selected = answers[currentQ];
  const isLast = currentQ === questions.length - 1;
  const bookmarked = isBookmarked(q.id);

  return (
    <div style={styles.screenPad}>
      <div style={styles.quizProgressRow}>
        <div style={styles.quizProgressText}>{t("Question", uiLanguage)} {currentQ + 1} {t("of", uiLanguage)} {questions.length}</div>
        <div style={styles.quizProgressBarTrack}>
          <div style={{ ...styles.quizProgressBarFill, width: `${((currentQ + 1) / questions.length) * 100}%`, transition: "width 0.35s ease" }} />
        </div>
      </div>

      <div style={styles.qCard} key={currentQ} className="cma-card-enter">
        <div style={styles.qCardTop}>
          <div style={{ flex: 1, minWidth: 0 }}>
            <div style={styles.qNumberLabel}>Q{currentQ + 1}.</div>
            <div style={styles.qText}>{qData.question}</div>
          </div>
          <button style={styles.bookmarkBtn} className="cma-tap-btn" onClick={() => onToggleBookmark(q)} aria-label="Bookmark question">
            <Star size={19} color={bookmarked ? palette.warn : palette.subtext2} fill={bookmarked ? palette.warn : "none"} />
          </button>
        </div>
        <div style={styles.optionsList}>
          {qData.options.map((opt, i) => {
            const isSelected = selected === i;
            const isCorrect = i === qData.correctIndex;
            let bg = palette.card, border = palette.border, textColor = palette.text;
            if (selected !== undefined) {
              if (isSelected && isCorrect) { bg = palette.successBg; border = palette.success; textColor = palette.success; }
              else if (isSelected && !isCorrect) { bg = palette.dangerBg; border = palette.danger; textColor = palette.danger; }
              else if (showCorrectAnswer && !isSelected && isCorrect) { bg = palette.successBg; border = palette.success; textColor = palette.success; }
            }
            return (
              <button
                key={i}
                style={{ ...styles.optionBtn, background: bg, borderColor: border, color: textColor, transition: "background 0.18s ease, border-color 0.18s ease" }}
                className={isSelected ? "cma-option-pop" : "cma-tap-btn"}
                onClick={() => selected === undefined && handleAnswer(currentQ, i)}
                disabled={selected !== undefined}
              >
                <span style={styles.optionLetter}>{String.fromCharCode(65 + i)}</span>
                <span style={styles.optionText}>{opt}</span>
                {selected !== undefined && isSelected && (isCorrect ? <CheckCircle2 size={18} color={palette.success} /> : <XCircle size={18} color={palette.danger} />)}
                {selected !== undefined && showCorrectAnswer && !isSelected && isCorrect && <CheckCircle2 size={18} color={palette.success} />}
              </button>
            );
          })}
        </div>
      </div>

      {showGoogleSearch && (
        <a
          href={`https://www.google.com/search?q=${encodeURIComponent(qData.question)}`}
          target="_blank"
          rel="noopener"
          style={styles.googleSearchBtn}
          className="cma-tap-btn"
        >
          <svg width="18" height="18" viewBox="0 0 48 48" aria-hidden="true">
            <path fill="#FFC107" d="M43.6 20.5H42V20H24v8h11.3c-1.6 4.7-6.1 8-11.3 8-6.6 0-12-5.4-12-12s5.4-12 12-12c3.1 0 5.9 1.2 8 3.1l5.7-5.7C34.6 6.1 29.6 4 24 4 12.9 4 4 12.9 4 24s8.9 20 20 20 20-8.9 20-20c0-1.3-.1-2.7-.4-3.5z" />
            <path fill="#FF3D00" d="M6.3 14.7l6.6 4.8C14.6 15.9 18.9 13 24 13c3.1 0 5.9 1.2 8 3.1l5.7-5.7C34.6 6.1 29.6 4 24 4 16.3 4 9.7 8.3 6.3 14.7z" />
            <path fill="#4CAF50" d="M24 44c5.5 0 10.4-1.9 14.3-5.1l-6.6-5.6C29.6 34.9 26.9 36 24 36c-5.2 0-9.6-3.3-11.3-8l-6.6 5.1C9.6 39.6 16.3 44 24 44z" />
            <path fill="#1976D2" d="M43.6 20.5H42V20H24v8h11.3c-.8 2.3-2.2 4.2-4.1 5.6l6.6 5.6C41.6 36 44 30.5 44 24c0-1.3-.1-2.7-.4-3.5z" />
          </svg>
          {t("Search on Google", uiLanguage)}
        </a>
      )}

      <div style={styles.quizNavRow}>
        <button className="cma-nav-btn" style={{ ...styles.navBtn, opacity: currentQ === 0 ? 0.4 : 1 }} onClick={() => setCurrentQ((c) => Math.max(0, c - 1))} disabled={currentQ === 0}>
          <ChevronLeft size={18} /> {t("Previous", uiLanguage)}
        </button>
        {isLast ? (
          <button className="cma-nav-btn" style={styles.navBtnPrimary} onClick={onFinish}>{t("Finish", uiLanguage)}</button>
        ) : (
          <button className="cma-nav-btn" style={styles.navBtnPrimary} onClick={() => setCurrentQ((c) => c + 1)}>{t("Next", uiLanguage)} <ChevronRight size={18} /></button>
        )}
      </div>
    </div>
  );
}

// ---------------------------------------------------------------------------
// RESULT SCREEN
// ---------------------------------------------------------------------------

function useCountUp(target, durationMs = 700) {
  const [value, setValue] = useState(0);
  React.useEffect(() => {
    let start = null;
    let raf;
    const step = (ts) => {
      if (start === null) start = ts;
      const progress = Math.min(1, (ts - start) / durationMs);
      const eased = 1 - Math.pow(1 - progress, 3); // ease-out cubic
      setValue(Math.round(eased * target));
      if (progress < 1) raf = requestAnimationFrame(step);
    };
    raf = requestAnimationFrame(step);
    return () => cancelAnimationFrame(raf);
  }, [target, durationMs]);
  return value;
}

function Confetti() {
  const { styles } = useTheme();
  const colors = ["#2f8f5f", "#c99a1e", "#d2691e", "#7a2f5f", "#1f5f8b", "#c0392b"];
  const pieces = Array.from({ length: 18 }, (_, i) => ({
    id: i,
    left: Math.round((i / 18) * 100 + (i % 2 === 0 ? -3 : 3)),
    delay: (i % 6) * 0.08,
    color: colors[i % colors.length],
    rotate: (i * 37) % 360,
  }));
  return (
    <div style={styles.confettiWrap} aria-hidden="true">
      {pieces.map((p) => (
        <span
          key={p.id}
          style={{
            ...styles.confettiPiece,
            left: `${p.left}%`,
            background: p.color,
            animation: `cmaConfettiFall 1.1s ease-in ${p.delay}s both`,
            transform: `rotate(${p.rotate}deg)`,
          }}
        />
      ))}
    </div>
  );
}

function ResultScreen({ score, onRetry, onHome, onChangeDifficulty, changeDifficultyLabel, homeLabel, uiLanguage }) {
  const { palette, styles } = useTheme();
  const pct = score.total > 0 ? Math.round((score.correct / score.total) * 100) : 0;
  const wrong = score.attempted - score.correct;
  const animatedPct = useCountUp(pct);
  const celebrate = pct >= 80 && score.total > 0;

  return (
    <div style={styles.screenPad}>
      <div style={styles.resultCard} className="cma-bounce-in">
        <div style={{ ...styles.resultRing, position: "relative" }}>
          {celebrate && <Confetti />}
          <div style={styles.resultPct}>{animatedPct}%</div>
        </div>
        {celebrate && (
          <div style={styles.celebrateRow}>
            <PartyPopper size={15} color={palette.warn} />
            <span>{t("Great job — that's a strong score!", uiLanguage)}</span>
          </div>
        )}
        <div style={styles.resultStatsRow}>
          <div style={styles.resultStat}>
            <div style={{ ...styles.resultStatNum, color: palette.success }}>{score.correct}</div>
            <div style={styles.resultStatLabel}>{t("Correct", uiLanguage)}</div>
          </div>
          <div style={styles.resultStat}>
            <div style={{ ...styles.resultStatNum, color: palette.danger }}>{wrong}</div>
            <div style={styles.resultStatLabel}>{t("Wrong", uiLanguage)}</div>
          </div>
          <div style={styles.resultStat}>
            <div style={{ ...styles.resultStatNum, color: palette.subtext2 }}>{score.total - score.attempted}</div>
            <div style={styles.resultStatLabel}>{t("Skipped", uiLanguage)}</div>
          </div>
        </div>
        {wrong > 0 && <div style={styles.resultNote}>{wrong} {wrong > 1 ? t("questions added to your Mistakes folder for revision.", uiLanguage) : t("question added to your Mistakes folder for revision.", uiLanguage)}</div>}
      </div>
      <div style={styles.resultActions}>
        <button className="cma-nav-btn" style={styles.navBtnPrimary} onClick={onRetry}><RotateCcw size={17} /> {t("Retry Quiz", uiLanguage)}</button>
        {onChangeDifficulty && <button className="cma-nav-btn" style={styles.navBtn} onClick={onChangeDifficulty}>{changeDifficultyLabel ? t(changeDifficultyLabel, uiLanguage) : t("Change Difficulty", uiLanguage)}</button>}
        <button className="cma-nav-btn" style={styles.navBtnGhost} onClick={onHome}>{homeLabel ? t(homeLabel, uiLanguage) : t("Back to Home", uiLanguage)}</button>
      </div>
    </div>
  );
}

