function SearchScreen({ onNavigate, uiLanguage }) {
  const { palette, styles } = useTheme();
  const [query, setQuery] = useState("");
  const [paperFilter, setPaperFilter] = useState("all"); // "all" or a paper id

  const scopedPapers = useMemo(
    () => (paperFilter === "all" ? SYLLABUS : SYLLABUS.filter((p) => p.id === paperFilter)),
    [paperFilter]
  );

  const results = useMemo(() => {
    const q = query.trim();
    if (!q) return [];
    const out = [];
    scopedPapers.forEach((paper) => {
      paper.sections.forEach((section) => {
        section.chapters.forEach((ch) => {
          if (fuzzyMatch(ch.title, q)) out.push({ type: "chapter", paper, chapter: ch });
          ch.topics.forEach((topic) => {
            if (fuzzyMatch(topic.title, q)) out.push({ type: "topic", paper, chapter: ch, topic });
          });
        });
      });
    });
    return out.slice(0, 40);
  }, [query, scopedPapers]);

  return (
    <div style={styles.screenPad}>
      <h2 style={styles.screenTitle}>{t("Search", uiLanguage)}</h2>
      <div style={styles.searchInputWrap}>
        <Search size={17} color={palette.subtext2} />
        <input
          style={styles.searchInput}
          placeholder={t("Search modules or units, e.g. 'Banking', 'Sayres'...", uiLanguage)}
          value={query}
          onChange={(e) => setQuery(e.target.value)}
        />
      </div>

      <div style={styles.paperFilterRow}>
        <button
          style={{ ...styles.paperFilterChip, ...(paperFilter === "all" ? styles.paperFilterChipActive : {}) }}
          onClick={() => setPaperFilter("all")}
        >
          {t("All Papers", uiLanguage)}
        </button>
        {SYLLABUS.map((p) => (
          <button
            key={p.id}
            style={{
              ...styles.paperFilterChip,
              ...(paperFilter === p.id ? { background: p.color, borderColor: p.color, color: "#fff" } : {}),
            }}
            onClick={() => setPaperFilter(p.id)}
          >
            {p.code}
          </button>
        ))}
      </div>

      {!query.trim() && (
        <div style={styles.suggestionsBlock}>
          <p style={styles.searchEmptyHint}>{t("Type a module or unit name to jump straight to it — no need to browse paper by paper.", uiLanguage)}</p>
          <div style={styles.suggestionChipsWrap}>
            {SEARCH_SUGGESTIONS.map((s, i) => (
              <button key={i} style={styles.suggestionChip} onClick={() => setQuery(s)}>
                {s}
              </button>
            ))}
          </div>
        </div>
      )}

      {query.trim() && results.length === 0 && (
        <div style={styles.emptyState}>
          <div style={styles.emptyIconCircle}><SearchX size={30} color={palette.subtext2} /></div>
          <h3 style={styles.emptyStateTitle}>{t("No matches", uiLanguage)}</h3>
          <p style={styles.emptyStateText}>{t("Try a different keyword", uiLanguage)}{paperFilter !== "all" ? t(", or search across all papers", uiLanguage) : ""}.</p>
        </div>
      )}

      <div style={styles.cardList}>
        {results.map((r, i) => (
          <button key={i} style={styles.searchResultCard} onClick={() => onNavigate(r)}>
            <div style={{ ...styles.searchResultTypeTag, background: r.paper.color }}>{r.type === "topic" ? t("Unit", uiLanguage) : t("Module", uiLanguage)}</div>
            <div style={styles.searchResultBody}>
              <div style={styles.searchResultTitle}>{r.type === "topic" ? r.topic.title : r.chapter.title}</div>
              <div style={styles.searchResultSub}>{r.paper.short}{r.type === "topic" ? ` · ${r.chapter.title}` : ""}</div>
            </div>
            <ChevronRight size={17} color={palette.subtext2} />
          </button>
        ))}
      </div>
    </div>
  );
}

