function CustomMockBuilderScreen({ paper, onStart, uiLanguage }) {
  const { palette, styles } = useTheme();
  const allChapters = useMemo(() => (paper ? paper.sections.flatMap((s) => s.chapters) : []), [paper]);
  const [selectedChapterIds, setSelectedChapterIds] = useState(() => allChapters.map((c) => c.id));
  const [selectedDifficultyIds, setSelectedDifficultyIds] = useState(() => DIFFICULTIES.map((d) => d.id));
  const [questionCount, setQuestionCount] = useState(50);

  if (!paper) return null;

  const availableCount = collectCustomMockMcqs(paper, selectedChapterIds, selectedDifficultyIds).length;
  const effectiveCount = Math.min(questionCount, availableCount);

  const toggleChapter = (id) => {
    setSelectedChapterIds((prev) => (prev.includes(id) ? prev.filter((x) => x !== id) : [...prev, id]));
  };
  const toggleDifficulty = (id) => {
    setSelectedDifficultyIds((prev) => (prev.includes(id) ? prev.filter((x) => x !== id) : [...prev, id]));
  };
  const allChaptersSelected = selectedChapterIds.length === allChapters.length;

  const countOptions = [10, 20, 30, 50, 75, 100];

  return (
    <div style={styles.screenPad}>
      <h2 style={styles.screenTitle}>{paper.title}</h2>
      <p style={styles.screenSub}>{t("Build a custom test from exactly what you want to practice.", uiLanguage)}</p>

      <div style={styles.builderSectionHeader}>
        <span>{t("Chapters", uiLanguage)}</span>
        <button
          style={styles.builderSelectAllBtn}
          onClick={() => setSelectedChapterIds(allChaptersSelected ? [] : allChapters.map((c) => c.id))}
        >
          {allChaptersSelected ? t("Deselect all", uiLanguage) : t("Select all", uiLanguage)}
        </button>
      </div>
      <div style={styles.builderChipWrap}>
        {allChapters.map((ch) => {
          const active = selectedChapterIds.includes(ch.id);
          return (
            <button
              key={ch.id}
              style={{ ...styles.builderChip, ...(active ? { background: paper.color, borderColor: paper.color, color: "#fff" } : {}) }}
              onClick={() => toggleChapter(ch.id)}
            >
              {ch.title}
            </button>
          );
        })}
      </div>

      <div style={styles.builderSectionHeader}>
        <span>{t("Difficulty", uiLanguage)}</span>
      </div>
      <div style={styles.builderChipWrap}>
        {DIFFICULTIES.map((d) => {
          const active = selectedDifficultyIds.includes(d.id);
          return (
            <button
              key={d.id}
              style={{ ...styles.builderChip, ...(active ? { background: d.color, borderColor: d.color, color: "#fff" } : {}) }}
              onClick={() => toggleDifficulty(d.id)}
            >
              {d.label}
            </button>
          );
        })}
      </div>

      <div style={styles.builderSectionHeader}>
        <span>{t("Number of questions", uiLanguage)}</span>
      </div>
      <div style={styles.builderChipWrap}>
        {countOptions.map((n) => (
          <button
            key={n}
            style={{ ...styles.builderChip, ...(questionCount === n ? { background: paper.color, borderColor: paper.color, color: "#fff" } : {}) }}
            onClick={() => setQuestionCount(n)}
          >
            {n}
          </button>
        ))}
      </div>

      <div style={styles.builderAvailableNote}>
        {availableCount} {availableCount === 1 ? t("question", uiLanguage) : t("questions", uiLanguage)} {t("match your selection", uiLanguage)}
        {availableCount > 0 && availableCount < questionCount ? ` — ${t("test will use all available", uiLanguage)} ${availableCount}` : ""}
      </div>

      <button
        className="cma-nav-btn"
        style={{ ...styles.navBtnPrimary, width: "100%", opacity: availableCount === 0 || selectedChapterIds.length === 0 || selectedDifficultyIds.length === 0 ? 0.5 : 1 }}
        disabled={availableCount === 0 || selectedChapterIds.length === 0 || selectedDifficultyIds.length === 0}
        onClick={() => onStart(selectedChapterIds, selectedDifficultyIds, effectiveCount)}
      >
        {t("Start Test", uiLanguage)} ({effectiveCount} {effectiveCount === 1 ? t("question", uiLanguage) : t("questions", uiLanguage)})
      </button>
    </div>
  );
}

