function SavedScreen({ bookmarks, mistakes, onToggleBookmark, language, uiLanguage }) {
  const { palette, styles } = useTheme();
  const [sub, setSub] = useState("bookmarks");
  const list = sub === "bookmarks" ? bookmarks : mistakes;

  return (
    <div style={styles.screenPad}>
      <h2 style={styles.screenTitle}>{t("Saved", uiLanguage)}</h2>
      <div style={styles.subTabRow}>
        <button style={{ ...styles.subTabBtn, ...(sub === "bookmarks" ? styles.subTabBtnActive : {}) }} onClick={() => setSub("bookmarks")}>
          {t("Bookmarked", uiLanguage)} ({bookmarks.length})
        </button>
        <button style={{ ...styles.subTabBtn, ...(sub === "mistakes" ? styles.subTabBtnActive : {}) }} onClick={() => setSub("mistakes")}>
          {t("Mistakes", uiLanguage)} ({mistakes.length})
        </button>
      </div>

      {list.length === 0 ? (
        <div style={styles.emptyState}>
          <div style={styles.emptyIconCircle}>
            {sub === "bookmarks" ? <Star size={28} color={palette.warn} /> : <Sparkles size={28} color={palette.subtext2} />}
          </div>
          <h3 style={styles.emptyStateTitle}>{sub === "bookmarks" ? t("No bookmarks yet", uiLanguage) : t("No mistakes yet", uiLanguage)}</h3>
          <p style={styles.emptyStateText}>
            {sub === "bookmarks" ? t("Tap the star on any question during practice to save it here.", uiLanguage) : t("Questions you get wrong will automatically show up here for revision.", uiLanguage)}
          </p>
        </div>
      ) : (
        <div style={styles.cardList}>
          {list.map((q) => {
            const qd = q[language] || q.en;
            return (
              <div key={q.id} style={styles.savedQCard}>
                <div style={styles.savedQMeta}>{q.chapterTitle}{q.topic ? ` · ${q.topic}` : ""}</div>
                <div style={styles.savedQText}>{qd?.question}</div>
                {sub === "mistakes" && qd?.options && (
                  <div style={styles.mistakeOptionsList}>
                    {qd.options.map((opt, i) => {
                      const isCorrect = i === qd.correctIndex;
                      return (
                        <div
                          key={i}
                          style={{
                            ...styles.mistakeOptionRow,
                            background: isCorrect ? palette.successBg : "transparent",
                            borderColor: isCorrect ? palette.success : palette.border,
                            color: isCorrect ? palette.success : palette.subtext,
                          }}
                        >
                          <span style={styles.optionLetter}>{String.fromCharCode(65 + i)}</span>
                          <span style={styles.optionText}>{opt}</span>
                          {isCorrect && <CheckCircle2 size={16} color={palette.success} />}
                        </div>
                      );
                    })}
                  </div>
                )}
                {sub === "bookmarks" && (
                  <button style={styles.unbookmarkBtn} onClick={() => onToggleBookmark(q)}>
                    <Star size={14} color={palette.warn} fill={palette.warn} /> {t("Remove", uiLanguage)}
                  </button>
                )}
              </div>
            );
          })}
        </div>
      )}
    </div>
  );
}

// ---------------------------------------------------------------------------
// SETTINGS TAB
// ---------------------------------------------------------------------------

// ---------------------------------------------------------------------------
// IN-APP PDF VIEWER
// ---------------------------------------------------------------------------

function PdfViewerScreen({ paper, uiLanguage }) {
  const { palette, styles } = useTheme();
  if (!paper) return null;
  return (
    <div style={styles.pdfViewerWrap}>
      <div style={styles.pdfViewerBar}>
        <span style={{ ...styles.paperTag, background: paper.color }}>{paper.code}</span>
        <span style={styles.pdfViewerTitle}>{t("Study Notes", uiLanguage)}</span>
      </div>
      <iframe
        title={`${paper.code} Study Notes`}
        src={paper.pdfPath}
        style={styles.pdfIframe}
      />
    </div>
  );
}

function SettingsScreen({ theme, onToggleTheme, onOpenStudyNotes, authUser, onLogOut, uiLanguage, setUiLanguage, soundEnabled, setSoundEnabled }) {
  const { palette, styles } = useTheme();
  return (
    <div style={styles.screenPad}>
      <h2 style={styles.screenTitle}>{t("Settings", uiLanguage)}</h2>

      {authUser && (
        <div style={styles.accountCard}>
          <div style={styles.accountAvatar}>{(authUser.name || authUser.email || "?").charAt(0).toUpperCase()}</div>
          <div style={{ flex: 1, minWidth: 0 }}>
            <div style={styles.accountName}>{authUser.name}</div>
            <div style={styles.accountEmail}>{authUser.email}</div>
          </div>
          <button className="cma-tap-btn" style={styles.logOutBtn} onClick={onLogOut}>{t("Log Out", uiLanguage)}</button>
        </div>
      )}

      <div style={styles.settingsRow}>
        <div>
          <div style={styles.settingsRowTitle}>{t("Dark Mode", uiLanguage)}</div>
          <div style={styles.settingsRowDesc}>{t("Switch between light and dark theme", uiLanguage)}</div>
        </div>
        <button style={{ ...styles.themeToggle, background: theme === "dark" ? palette.accent : palette.chipBg }} onClick={onToggleTheme} aria-label={t("Toggle dark mode", uiLanguage)}>
          <span style={{ ...styles.themeToggleDot, transform: theme === "dark" ? "translateX(20px)" : "translateX(2px)" }}>
            {theme === "dark" ? <Moon size={12} color="#fff" /> : <Sun size={12} color="#c99a1e" />}
          </span>
        </button>
      </div>

      {setSoundEnabled && (
        <div style={styles.settingsRow}>
          <div>
            <div style={styles.settingsRowTitle}>{t("Sound Effects", uiLanguage)}</div>
            <div style={styles.settingsRowDesc}>{t("Play a sound for correct/incorrect answers and quiz completion", uiLanguage)}</div>
          </div>
          <button
            style={{ ...styles.themeToggle, background: soundEnabled ? palette.accent : palette.chipBg }}
            onClick={() => { setSoundEnabled((v) => !v); if (!soundEnabled) playSound("correct", true); }}
            aria-label={t("Toggle sound effects", uiLanguage)}
          >
            <span style={{ ...styles.themeToggleDot, transform: soundEnabled ? "translateX(20px)" : "translateX(2px)" }}>
              {soundEnabled ? <Volume2 size={12} color="#fff" /> : <VolumeX size={12} color={palette.subtext2} />}
            </span>
          </button>
        </div>
      )}

      {setUiLanguage && (
        <div style={styles.settingsRow}>
          <div>
            <div style={styles.settingsRowTitle}>{t("App Language", uiLanguage)}</div>
            <div style={styles.settingsRowDesc}>{t("Change the app's own menus and buttons. This does not affect the language of MCQ questions.", uiLanguage)}</div>
          </div>
          <div style={styles.appLangToggleGroup}>
            <button
              style={{ ...styles.appLangToggleBtn, ...(uiLanguage === "en" ? styles.appLangToggleBtnActive : {}) }}
              onClick={() => setUiLanguage("en")}
            >
              English
            </button>
            <button
              style={{ ...styles.appLangToggleBtn, ...(uiLanguage === "hi" ? styles.appLangToggleBtnActive : {}) }}
              onClick={() => setUiLanguage("hi")}
            >
              हिंदी
            </button>
          </div>
        </div>
      )}

      <div style={styles.settingsSectionLabel}>{t("Study Material", uiLanguage)}</div>
      <div style={styles.cardList}>
        {SYLLABUS.map((paper) => (
          <button key={paper.id} className="cma-tap-btn" style={styles.pdfDownloadCard} onClick={() => onOpenStudyNotes(paper)}>
            <div style={{ ...styles.pdfDownloadIconWrap, background: `${paper.color}1a` }}>
              <BookOpen size={16} color={paper.color} />
            </div>
            <div style={styles.pdfDownloadBody}>
              <div style={styles.pdfDownloadTitle}>{paper.code} — {t("Study Notes", uiLanguage)}</div>
              <div style={styles.pdfDownloadSub}>{paper.short}</div>
            </div>
            <ChevronRight size={17} color={palette.subtext2} />
          </button>
        ))}
      </div>

      <div style={styles.settingsInfoCard}>
        <div style={styles.settingsInfoTitle}>{t("About this app", uiLanguage)}</div>
        <div style={styles.settingsInfoText}>{t("CMA Foundation MCQ Practice — built around the current ICMAI Syllabus 2022, covering all 4 papers. Questions are added progressively across topics, chapters, and difficulty levels. Official study notes PDFs are available for offline reading in the Study Material section above.", uiLanguage)}</div>
      </div>
    </div>
  );
}

