    resultActions: { display: "flex", flexDirection: "column", gap: 10 },

    searchInputWrap: { display: "flex", alignItems: "center", gap: 9, background: p.cardAlt, border: `1.5px solid ${p.border}`, borderRadius: 13, padding: "12px 14px", marginBottom: 14 },
