    paperFilterChipActive: { background: p.accentBgSoft, borderColor: p.accent, color: p.accent },
    suggestionsBlock: { marginBottom: 6 },
    suggestionChipsWrap: { display: "flex", flexWrap: "wrap", gap: 8, marginTop: 4 },
