    scannerSubTabBtnActive: { background: p.accent, borderColor: p.accent, color: "#fff" },

    notesModuleCard: { background: p.card, border: `1px solid ${p.borderSoft}`, borderRadius: 14, padding: 0, boxShadow: p.cardShadow, overflow: "hidden" },
