    accountCard: { display: "flex", alignItems: "center", gap: 12, background: p.cardAlt, border: `1px solid ${p.border}`, borderRadius: 14, padding: "14px 16px", marginBottom: 16 },
    accountAvatar: { width: 42, height: 42, borderRadius: "50%", background: p.accent, color: "#fff", fontSize: 17, fontWeight: 700, display: "flex", alignItems: "center", justifyContent: "center", flexShrink: 0 },
