    accountEmail: { fontSize: 11.5, color: p.subtext2, overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" },
    logOutBtn: { flexShrink: 0, padding: "8px 13px", borderRadius: 10, border: `1.5px solid ${p.border}`, background: p.card, fontSize: 11.5, fontWeight: 700, color: p.danger, cursor: "pointer" },
    settingsRow: { display: "flex", alignItems: "center", justifyContent: "space-between", background: p.card, border: `1px solid ${p.border}`, borderRadius: 14, padding: "16px 16px", marginBottom: 14 },
    settingsRowTitle: { fontSize: 14, fontWeight: 700, color: p.text, marginBottom: 3 },
