    bottomNav: {
      position: "sticky", bottom: 0, left: 0, right: 0, background: p.navBg, borderTop: `1px solid ${p.navBorder}`,
      display: "flex", padding: "8px 4px calc(8px + env(safe-area-inset-bottom, 0px)) 4px", zIndex: 20,
    },
    navItem: { flex: 1, display: "flex", flexDirection: "column", alignItems: "center", gap: 4, border: "none", background: "transparent", cursor: "pointer", padding: "4px 2px" },
    navItemIcon: { width: 38, height: 30, display: "flex", alignItems: "center", justifyContent: "center", borderRadius: 12 },
    navItemIconActive: { width: 38, height: 30, display: "flex", alignItems: "center", justifyContent: "center", borderRadius: 12, background: p.accent },
    navLabel: { fontSize: 10 },
